import{c as e,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Researchers show that Claude Code is 98% not AI.","description":"","frontmatter":{"url":"https://x.com/HowToPrompt__/status/2066387618317869128","title":"Researchers show that Claude Code is 98% not AI.","author":"How To Prompt","archived":"2026-06-18T00:00:00.000Z","category":"deep-application","handle":"@HowToPrompt__","published":"2026-06-15T00:00:00.000Z","score":7.3,"stats":"2124❤ · 411 retweets","tags":["claude-code-architecture","reverse-engineering","harness-engineering","deterministic-code"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-15-@HowToPrompt__-869128.md","filePath":"research/tweets/2026-06-15-@HowToPrompt__-869128.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-06-15-@HowToPrompt__-869128.md"};function d(i,t,n,h,l,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="researchers-show-that-claude-code-is-98-not-ai-—-howtoprompt" tabindex="-1">Researchers show that Claude Code is 98% not AI — @HowToPrompt__ <a class="header-anchor" href="#researchers-show-that-claude-code-is-98-not-ai-—-howtoprompt" aria-label="Permalink to &quot;Researchers show that Claude Code is 98% not AI — @HowToPrompt__&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/HowToPrompt__/status/2066387618317869128" target="_blank" rel="noreferrer">https://x.com/HowToPrompt__/status/2066387618317869128</a><strong>類別</strong>：deep-application <strong>統計</strong>：2124❤ · 411 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Researchers show that Claude Code is 98% not AI.</p><p>Anthropic never gave us the architecture for Claude Code. There were no docs. Just a tool that every developer is currently obsessing over.</p><p>Until it leaked recently.</p><p>A research team pulled the source code, analyzed all 500,000 lines, and found something ridiculous.</p><p>Only 1.6% of the codebase actually interacts with the AI model.</p><p>The core of Claude Code is literally just a simple while-loop. It asks the model what to do, runs a tool, and repeats.</p><p>So what is the other 98.4%?</p><p>It is hardcore, traditional software engineering.</p><p>The researchers found a massive, complex infrastructure designed entirely to babysit the AI and keep it from hallucinating or destroying your computer:</p><ul><li>A 7-mode permission system acting as a security bouncer.</li><li>A 5-layer context compaction pipeline so the AI doesn&#39;t forget its goal.</li><li>A subagent delegation mechanism with strict worktree isolation.</li><li>Four different extensibility hooks to manage external tools safely.</li></ul><p>Every startup right now is trying to build a better AI model to get better results.</p><p>Anthropic did the exact opposite.</p><p>They took an existing model and built a fortress of deterministic software around it.</p><p>They realized that the AI doesn&#39;t need to be smarter. It needs to be managed.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>直接揭露 Claude Code 架構設計哲學，影響 harness 與 hook 設計決策</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>將技術研究轉為清晰的架構敘事（deterministic fortress &gt; smart model）</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>引用 500K 行逆向工程分析，具體數字（1.6% AI、7-mode 等），推文上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>列出 7 大架構組件：權限系統、compaction pipeline、worktree 隔離、extensibility hooks</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>「AI 需要被管理而非更聰明」原則適用所有 harness 設計</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.3/10</strong></td><td>8×0.3+7×0.2+6×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL（harness-engineering 架構認知） <strong>理由</strong>：直接支援 harness 設計決策——確定性代碼佔主導，AI 只做判斷；可升級為 harness-meta GOTCHAS 補充</p>',22)])])}const m=e(s,[["render",d]]);export{u as __pageData,m as default};
